// ============================================================================
// Test harness - Assert Test Environment
// ----------------------------------------------------------------------------
// FAO-GOV-001 / FAO-GOV-008: harnesses write real runs and ledger rows, so
// they may run only on an n8n instance started for tests (FAO_ENV=test) and
// only against local targets. Every URL this harness calls (FAO_TEST_SUPABASE_URL, FAO_TEST_INVOKE_URL)
// must be http or https, with no user info, to a local host: localhost,
// 127.0.0.1, [::1], a name ending in .localhost or .test, or a single-label
// name that starts with a letter (a Docker service name such as
// supabase_kong_<project>, which resolves only on the local network). A
// hosted project (for example <ref>.supabase.co) or any dotted or numeric
// address is refused. Otherwise this node throws before any request is made.
// ============================================================================

if (!$env || $env.FAO_ENV !== 'test') {
  throw new Error('FAO-GOV-008 harness: FAO_ENV is not test; refusing to run');
}

const TARGETS = ['FAO_TEST_SUPABASE_URL', 'FAO_TEST_INVOKE_URL'];
const URL_RE = /^https?:\/\/(\[::1\]|[A-Za-z0-9._-]+)(:[0-9]{1,5})?(\/[^\s]*)?$/;
const LOOPBACK = ['localhost', '127.0.0.1', '[::1]'];
const isLocal = (host) => {
  const h = host.toLowerCase();
  return LOOPBACK.includes(h) || h.endsWith('.localhost') || h.endsWith('.test') || /^[a-z][a-z0-9_-]{0,62}$/.test(h);
};

for (const name of TARGETS) {
  const m = URL_RE.exec(String($env[name] || ''));
  if (!m || !isLocal(m[1])) {
    throw new Error(`FAO-GOV-008 harness: ${name} is not a local target; refusing to run`);
  }
}

return [{ json: { fao_env: 'test' } }];

// ============================================================================
// Notifier harness - Assert Accepted
// ----------------------------------------------------------------------------
// FAO-GOV-007 / FAO-GOV-008: the invoke webhook accepted the run token with
// HTTP 202 and {accepted: true, correlation_id}. The flagship then runs and,
// when review is needed, calls the notifier with {hitl_id, kind, level}.
// ============================================================================

const res = (($input.first() || {}).json) || {};
let body = res.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (err) { body = null; }
}

if (res.statusCode !== 202 || !body || body.accepted !== true) {
  throw new Error(`FAO-GOV-007 harness: invoke webhook returned ${res.statusCode}, expected 202 accepted`);
}

return [{ json: { accepted: true, correlation_id: body.correlation_id } }];
